/** Writes docs/BOOK_DESIGNS.md from the design registry (so the uncertainty lists can never drift from the code). Run: npm run docs:designs */
import { writeFileSync } from 'node:fs';
import { DESIGNS } from '../src/art/index';
import { physicalLibrary, shasVolumes } from '../src/catalogue';

const vols = [...physicalLibrary.volumes, ...shasVolumes()];
const out: string[] = [];
out.push('# Book designs — vector recreations of the physical seforim', '',
  '*Generated by `npm run docs:designs` from `src/art/designs/*.ts`. Do not edit by hand.*', '',
  'Every cover, spine and back is **drawn from scratch as SVG** (millimetre geometry, real Hebrew fonts, SVG-filter materials) and rasterised on demand for the 3D books at the resolution the quality tier needs. The photographs the user supplied were used only as measuring blueprints: no photograph is shipped, pasted, cropped or wrapped onto any book (`tests/art.test.ts` enforces: no `<image>`, no bitmap data, nothing in `public/books`).', '',
  'The Kehot publisher mark is a vector trace (`scripts/trace-kehot.py`) of the logo file the user supplied; the other ornaments are redrawn by eye.', '',
  'Side-by-side comparisons of each recreation against its blueprint are in `docs/screenshots/lab-*.png`; presented in 3D: `docs/screenshots/covers-sheet.png`.', '');
for (const d of Object.values(DESIGNS)) {
  if (!d) continue;
  const used = vols.filter((v) => v.design?.id === d.id);
  const sizes = [...new Set(used.map((v) => `${v.size.h}×${v.size.w}×${v.size.t}`))].join(', ');
  out.push(`## ${d.name}`, '', `* Design id: \`${d.id}\` · volumes using it: ${used.length}`, `* Blueprint: ${d.reference}`, `* Size used (h×w×t cm): ${sizes}`, `* Binding / edge colours: \`${d.bindingColor}\` / \`${d.edgeColor}\``, '', '**Could not be established from the reference (approximated — verify against the physical book):**', '', ...d.uncertain.map((u) => `* ${u}`), '');
}
writeFileSync('docs/BOOK_DESIGNS.md', out.join('\n') + '\n');
console.log('wrote docs/BOOK_DESIGNS.md');
